import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { remove } from "../../../icons";
import { plus } from "../../../icons/index";
import { addConstructedStyle } from "../../utils/browser";
import { generateShortID } from "../../utils/function-helper";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import {
	getCssRulesForSentiment,
	getCssRulesForSentimentTag,
} from "../../utils/sentiments";
import { hasSlot } from "../../utils/slot";

/**
 * @since 0.0.12
 * @status stable
 *
 * @data-testid remove-button - The remove control rendered when the tag is removable.
 *
 * @description Tags are Used to categorize or mark by dimension or property.
 *
 * @slot - The tag's content.
 * @slot prefix - Used to prepend an icon or similar element to the button
 *
 * @part base - The component's base wrapper.
 * @part content - The tag content.
 * @part remove-button - The remove button.
 * @part prefix - The prefix container.
 * @part add - The addable input for add variant only.
 */

@Component({
	tag: "hbr-tag",
	styleUrl: "tag.scss",
	shadow: true,
})
export class Tag {
	sheet: CSSStyleSheet = new CSSStyleSheet();
	tag?: HTMLElement;
	selectable?: boolean;
	input?: HTMLInputElement;
	hiddenText?: HTMLSpanElement;
	selectChild?: boolean; //tag is being used inside of the hbr-select

	@Element() host!: HTMLHbrTagElement;

	/** The tag's type. */
	@Prop({ reflect: true }) variant: "label" | "selectable" | "add" = "label"; //"input" is not available yet

	/** The tag's sentiment. */
	@Prop({ reflect: true }) sentiment:
		| "success"
		| "positive" //Magnetic specific
		| "info"
		| "low-warning"
		| "warning"
		| "severe-warning"
		| "danger"
		| "negative" // Magnetic specific
		| "excellent"
		| "inactive"
		| "in-progress"
		| "disabled"
		| undefined;

	/** Set to true if tag is a uses monospace font family. @version: 2.12.5 */
	@Prop({ reflect: true }) mono = false;

	/** The tag's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** accent colors as background for colored tags, takes any css color values. Recommended to use accent colors from the design system */
	@Prop({ reflect: true }) accent?: string;

	/** Set to true to draw a pill-style tag with rounded edges. Default style. */
	@Prop({ reflect: true }) pill = true;

	/** Set to true to get status tag styles like larger prefix icons, lesser margin*/
	@Prop({ reflect: true }) status = false;

	/** Set to true to make the tag removable. */
	@Prop({ reflect: true }) removable = false;

	/** Set to true if selected. */
	@Prop({ mutable: true, reflect: true }) selected = false;

	/** Category tag */
	@Prop({ reflect: true }) category = false;

	/** Set to true to disable the select control. */
	@Prop({ reflect: true }) disabled = false;

	@Prop() uniqueid?: string;

	@Prop() placeholder = "Add";

	/** The add input's value attribute. */
	@Prop({ mutable: true, reflect: true }) value = "";

	/** The add input's maxlength attribute. */
	@Prop({ mutable: true }) maxlength = 20;

	/** overflow tag */
	@Prop({ reflect: true, mutable: true }) nested?: boolean;

	@Prop({ reflect: true }) overflow?: boolean;

	/** Wrap the text. */
	@Prop({ reflect: true }) wrap?: boolean;

	/** Use case for the 'word-break: break-all' instead of using 'break-word'. */
	@Prop() breakAll?: boolean;

	private arialabel = "";

	@State() hasPrefix = false;
	@State() hasSuffix = false;
	@State() hasFocus = false;
	@State() uuid: string = generateShortID();
	@State() removeHovered = false;

	/** Emitted when the remove button is activated. */
	@Event({ eventName: "hbr-remove" })
	hbrRemove!: EventEmitter;

	/** Emitted when click. */
	@Event({ eventName: "hbr-click" })
	hbrClick!: EventEmitter;

	/** Emitted when the add input's checked state changes. */
	@Event({ eventName: "hbr-change" })
	hbrChange!: EventEmitter;

	/** Emitted when the add input receives input. */
	@Event({ eventName: "hbr-input" })
	hbrInput!: EventEmitter;

	/** Emitted when the add input gains focus. */
	@Event({ eventName: "hbr-focus" })
	hbrFocus!: EventEmitter;

	/** Emitted when the add input loses focus. */
	@Event({ eventName: "hbr-blur" })
	hbrBlur!: EventEmitter;

	@Watch("selected")
	handleSelectedChange() {
		this.hbrChange.emit();
	}

	/** Sets focus on the add input. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.input?.focus(options);
	}

	/** Removes focus from the add input. */
	@Method()
	async removeFocus() {
		this.input?.blur();
	}

	connectedCallback() {
		this.handleRemoveClick = this.handleRemoveClick.bind(this);
		this.handleKeyDownRemoveClick = this.handleKeyDownRemoveClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleChange = this.handleChange.bind(this);
		this.handleInput = this.handleInput.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleInputKeyDown = this.handleInputKeyDown.bind(this);
		this.handleRemoveMouseEnter = this.handleRemoveMouseEnter.bind(this);
		this.handleRemoveMouseLeave = this.handleRemoveMouseLeave.bind(this);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}
	componentWillRender() {
		if (this.variant === "selectable") {
			this.selectable = true;
			this.arialabel = this.host.textContent || "Selectable Tag";
		}
	}

	handleRemoveClick() {
		this.hbrRemove.emit();
	}

	handleKeyDownRemoveClick(event: KeyboardEvent) {
		if (event.code === "Enter") {
			event.preventDefault();
			event.stopPropagation();
			this.hbrRemove.emit();
		}
	}

	handleRemoveMouseEnter() {
		/** adding .tag--remove-hovered since :has(.remove-button:hover) doesn't work due to shadowDOM */
		this.removeHovered = true;
	}

	handleRemoveMouseLeave() {
		this.removeHovered = false;
	}

	handleSlotChange() {
		this.selectChild =
			this.host.parentElement?.classList.contains("select__tags");
		this.hasPrefix = this.variant === "add" || hasSlot(this.host, "prefix");
		this.hasSuffix = hasSlot(this.host, "suffix");
	}

	handleKeyDown(event: KeyboardEvent) {
		if (event.key === " ") {
			event.preventDefault();
		}
	}

	handleChange() {
		this.value = this.input?.value || "";
		this.hbrChange.emit();
		/** Reset */
		if (this.input) {
			this.input.value = "";
		}
		if (this.hiddenText) {
			this.hiddenText.textContent = this.placeholder;
		}
	}

	handleInput() {
		const { value } = this.input || {};
		this.value = value || "";
		if (this.hiddenText) {
			this.hiddenText.textContent = value || "";
		}
		this.hbrInput.emit();
	}

	handleBlur() {
		this.hasFocus = false;
		this.host.setAttribute("data-focused", "false");
		this.hbrBlur.emit();
	}

	handleFocus() {
		this.hasFocus = true;
		this.host.setAttribute("data-focused", "true");
		this.hbrFocus.emit();
	}

	handleInputKeyDown(event: KeyboardEvent) {
		if (event.key === "Enter") {
			this.hbrChange.emit();

			/** Reset */
			if (this.input) {
				this.input.value = "";
			}
			if (this.hiddenText) {
				this.hiddenText.textContent = this.placeholder;
			}
		}
	}

	handleClickTag() {
		this.hbrClick.emit();
	}

	handleKeyUp(event: KeyboardEvent) {
		let flag = false;
		const { key } = event as KeyboardEvent;
		const target = event.target as HTMLElement;
		switch (key) {
			case " ":
				target.click();
				flag = true;
				break;
			default:
				break;
		}
		if (flag) {
			event.stopPropagation();
		}
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const { variant, sentiment, size, selectable } = this;
		const thisId = this.uniqueid || `tag-selectable-${this.uuid}`;
		const part = `base${this.hasPrefix ? " base-prefix" : ""}${
			this.hasSuffix ? " base-suffix" : ""
		}`;
		let selectableID = {};
		if (selectable) {
			selectableID = { id: thisId };
		}

		const textLabel = (this.host.textContent ?? "").trim() || "Remove";

		let a11yForSelectable = {};
		if (selectable) {
			a11yForSelectable = {
				...a11yForSelectable,
				tabIndex: 0,
				role: "checkbox",
				"aria-checked": this.selected ? "true" : "false",
			};
			if (!this.nested) {
				//ToDo key event on nested
				a11yForSelectable = {
					...a11yForSelectable,
					onKeyDown: this.handleKeyDown.bind(this),
					onKeyUp: this.handleKeyUp.bind(this),
				};
			}
		}

		if (this.host) {
			const { sentiment, accent } = this;
			const isAccent = !!accent && accent?.startsWith("var(--accent-");
			let accentBgColor = "transparent";
			let accentBgHover = "transparent";
			let accentTextColor = "var(--base-text-default)";
			let accentIconColor = "var(--remove-icon-color)";

			if (isAccent) {
				const accentBase = accent.endsWith("-default)")
					? accent.replace("-default)", ")")
					: accent;
				accentBgColor = `${accentBase.slice(0, -1)}-default)`;
				accentBgHover = `var(${accentBase.slice(4, -1)}-hover)`;

				if (accentBase.includes("-strong")) {
					accentTextColor = "var(--base-text-in-default)";
					accentIconColor = "var(--base-icon-in-default)";
				}
			} else {
				accentBgColor = accent ? accent : "transparent";
			}

			const sentimentStyles = sentiment
				? `
					.tag--sentiment {
						${getCssRulesForSentimentTag({ sentiment })}
					}
					.tag__icon,
					.tag__prefix-icon {
						${getCssRulesForSentiment({
							sentiment,
							type: "icon",
						})}
					}
				`
				: "";

			this.sheet.replaceSync(`
				.tag--colored {
					--accent-bg-color: ${accentBgColor};
					--accent-bg-color-hover: ${accentBgHover};
					--accent-text-color: ${accentTextColor};
					--accent-icon-color: ${accentIconColor};
				}
				${sentimentStyles}
			`);

			addConstructedStyle(this.host.shadowRoot, this.sheet);
		}

		return (
			<Host>
				<span
					ref={(el) => {
						this.tag = el;
					}}
					part={part}
					class={{
						tag: true,
						"tag--mono": this.mono,

						// Types
						"tag--label": variant === "label",
						"tag--add": variant === "add",
						"tag--selectable": !!selectable,

						// sentiment
						"tag--sentiment": !!sentiment,

						// Sizes
						"tag--small": size === "small",
						"tag--medium": size === "medium",
						"tag--large": size === "large",

						// Modifiers
						"tag--pill": this.pill,
						"tag--removable": this.removable,
						"tag--has-prefix": this.hasPrefix,
						"tag--has-suffix": this.hasSuffix,
						"tag--category": this.category,
						"tag--disabled": this.disabled,
						"tag--focused": this.hasFocus,
						"tag--remove-hovered": this.removeHovered,
						"tag--selected": this.selected,
						"tag--nested": !!this.nested,
						"tag--colored": !!this.accent,
						"tag--select-child": !!this.selectChild,
						"tag--overflow": !!this.overflow,
						"tag--status": !!this.status,
						"tag--wrap": !!this.wrap,
					}}
					{...(!this.nested && !this.disabled && selectable
						? { onClick: this.handleClickTag.bind(this) }
						: {})}
				>
					{selectable ? (
						<span
							{...a11yForSelectable}
							class="tag__hidden-container"
							aria-label={this.arialabel}
							aria-checked={this.selected ? "true" : "false"}
						/>
					) : (
						""
					)}
					{this.variant === "add" ? (
						<Fragment>
							<span class="tag__add-container">
								<span part="prefix" class="tag__prefix">
									<slot onSlotchange={this.handleSlotChange} name="prefix" />
									<hbr-icon
										asset={customSystemIcons?.plus || plus}
										size={this.size === "small" ? "12px" : "14px"}
										class={"plus-icon"}
									/>
								</span>
								<input
									part="add"
									id={`tag-input--${thisId}`}
									class={"tag__add"}
									ref={(el) => {
										this.input = el;
									}}
									placeholder={this.placeholder}
									disabled={this.disabled}
									onChange={this.handleChange}
									onInput={this.handleInput}
									onFocus={this.handleFocus}
									onBlur={this.handleBlur}
									onKeyDown={this.handleInputKeyDown}
									maxlength={this.maxlength}
								/>
								<span part="suffix" class="tag__suffix">
									<slot onSlotchange={this.handleSlotChange} name="suffix" />
								</span>
							</span>
							<span
								class="tag__add-hidden-text"
								ref={(el) => {
									this.hiddenText = el;
								}}
							>
								{this.placeholder}
							</span>
						</Fragment>
					) : (
						<Fragment>
							<span
								part="prefix"
								class={{
									tag__prefix: true,
									"tag__prefix-icon": !!this.sentiment,
								}}
							>
								<slot onSlotchange={this.handleSlotChange} name="prefix" />
							</span>
							<span
								part="content"
								class={`tag__content ${
									this.breakAll ? "tag__content-break-all" : ""
								}`}
								{...selectableID}
							>
								<slot onSlotchange={this.handleSlotChange} />
							</span>
							<span part="suffix" class="tag__suffix">
								<slot onSlotchange={this.handleSlotChange} name="suffix" />
							</span>
						</Fragment>
					)}
					{this.removable && (
						<hbr-icon-button
							exportparts="base:remove-button"
							asset={customSystemIcons?.remove || remove}
							class="tag__remove"
							arialabel={`Remove ${textLabel}`}
							onMouseEnter={this.handleRemoveMouseEnter}
							onMouseLeave={this.handleRemoveMouseLeave}
							onClick={this.handleRemoveClick}
							onKeyDown={this.handleKeyDownRemoveClick}
							data-testid="remove-button"
						/>
					)}
				</span>
			</Host>
		);
	}
}
